import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BXzK3EA4.js";const r="/assets/Angel%20TOTP.D42MmgDL.webp",i="/assets/Google-Authenticator.CGZrpZ3D.webp",s="/assets/image%20(83).CvkJgY6J.png",m=JSON.parse('{"title":"AngelOne","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/angelone.md","filePath":"connect-brokers/brokers/angelone.md"}'),l={name:"connect-brokers/brokers/angelone.md"};function c(g,e,p,h,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="angelone" tabindex="-1">AngelOne <a class="header-anchor" href="#angelone" aria-label="Permalink to &quot;AngelOne&quot;">​</a></h1><p>AngelOne, previously known as Angel Broking, is a prominent Indian stock brokerage firm offering a wide range of trading and investment services. For developers and fintech companies looking to integrate algorithmic trading capabilities, AngelOne provides an API gateway through its platform. This API, often referred to in the context of Tradeboard integration, enables automated trading strategies, real-time market data access, and more.</p><p>The introductory phase of integrating with AngelOne&#39;s API typically involves:</p><p><strong>Enable TOTP</strong>: Developers must register for an API key through AngelOne&#39;s developer portal, which serves as the authentication mechanism for API requests.</p><h3 id="what-is-2-factor-authentication-2-fa" tabindex="-1"><strong>What is 2-factor authentication (2-FA)?</strong> <a href="#what-is-2-factor-authentication-2-fa-3" id="what-is-2-factor-authentication-2-fa-3"></a> <a class="header-anchor" href="#what-is-2-factor-authentication-2-fa" aria-label="Permalink to &quot;**What is 2-factor authentication (2-FA)?** &lt;a href=&quot;#what-is-2-factor-authentication-2-fa-3&quot; id=&quot;what-is-2-factor-authentication-2-fa-3&quot;&gt;&lt;/a&gt;&quot;">​</a></h3><p>The 2FA or 2-factor authentication is a user authentication process where brokers offer to traders/investors any two of the following three types of authentication mechanisms to users for logging in to their online trading account-</p><ol><li>Knowledge factor (i.e. something that only the user knows) e.g. PIN, password, etc.</li><li>Possession factor (i.e. something that only the user has) e.g. OTP, security token, authenticator apps on smartphones, etc.</li><li>Biometrics (i.e. biological identity markers of the person) e.g. fingerprint, face id, pattern, etc.</li></ol><h3 id="manual-totp-generation-process-using-google-authenticator" tabindex="-1">Manual TOTP Generation Process using Google Authenticator <a class="header-anchor" href="#manual-totp-generation-process-using-google-authenticator" aria-label="Permalink to &quot;Manual TOTP Generation Process using Google Authenticator&quot;">​</a></h3><p>Step 1: Visit <a href="http://smartapi.angelbroking.com/enable-totp" target="_blank" rel="noreferrer">smartapi.angelbroking.com/enable-totp</a></p><p><br> Step 2: Enter your Angel One client id and trading terminal password <strong>or MPIN</strong><br> Step 3: Enter the OTP sent to the Registered email &amp; mobile. Once OTP is entered, you will see a QR code on the screen and a token number on the screen.</p><figure><img src="'+r+'" alt=""><figcaption><p>Enable TOTP</p></figcaption></figure><p><br> Step 4: Open the <strong>Google Authenticator App</strong>. Install it from the Android Playstore or Apple Store<br> Step 5: Scan the QR code generated from our site on your authenticator app</p><p>Google authenticator now generates TOTP(Time-based OTP) and it is valid for 60 seconds. Use this for manual TOTP verification</p><figure><img src="'+i+'" alt=""><figcaption><p>Google Authenticator</p></figcaption></figure><figure><img src="'+s+`" alt=""><figcaption></figcaption></figure><p><strong>API Key Registration</strong>: Developers must register for an API key through AngelOne&#39;s developer portal, which serves as the authentication mechanism for API requests.</p><p>Goto the <a href="https://smartapi.angelbroking.com/signin" target="_blank" rel="noreferrer">Smart API Developer Portal</a> and login with your credentials. sign up if you are a new user.</p><p>Enter the App name, Redirect URL (use dummy url <a href="https://google.com" target="_blank" rel="noreferrer">https://google.com</a>) and your Angel Client ID</p><p>Save the generated apikey. Later we will be adding the apikey in the <a href="https://docs.algo.wesoftcorp.com/getting-started/windows-installation/environmental-variables" target="_blank" rel="noreferrer">environmental variable</a></p><p>Here is a sample of how the details would appear in a .env file for reference:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BROKER_API_KEY = &#39;your_api_key_here&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;your_api_secret_here&#39;</span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/angel/callback&#39;</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Only <code>BROKER_API_KEY</code> is used by the AngelOne plugin. The login is a TOTP exchange rather than an OAuth code exchange, so no API secret is ever sent. Leave <code>BROKER_API_SECRET</code> at its placeholder if SmartAPI did not give you one.</p></div><h3 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h3><p>Clicking Connect opens the AngelOne login form, which asks for three values:</p><ul><li><strong>Client ID</strong>, your Angel One client code</li><li><strong>PIN</strong>, your trading PIN or password</li><li><strong>TOTP</strong>, the current 6-digit code from the authenticator app you enrolled above</li></ul><p>Integrating Tradeboard with AngelOne&#39;s API opens up possibilities for automated trading strategies, providing a powerful tool for traders and developers to exploit market opportunities efficiently. It&#39;s essential to follow best practices for API integration, including handling rate limits, managing API keys securely, and ensuring robust error handling and logging mechanisms are in place.</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/angel/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>MCX</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code>, <code>MCX_INDEX</code></li></ul>`,29)])])}const b=t(l,[["render",c]]);export{m as __pageData,b as default};
